# owner: platform
import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span

def make_shift(worker, start, end, day="mon"):
    return Shift(worker, day, Span(start, end))

class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        shifts = [
            make_shift("Brisa", 540, 600),
            make_shift("Caleb", 540, 840),
            make_shift("Brisa", 600, 630, "tue"),
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            ["Caleb: 1 shifts, 5.0 hours", "Brisa: 2 shifts, 1.5 hours"],
        )

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker(self):
        with self.assertRaises(ValueError):
            timesheet_lines([make_shift("  ", 540, 600)])
